#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.Grenade)]
    public class Grenade : EntityBehaviourDefinition
    {
        public Grenade(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            entity.SetCollisionMaskHostile(0);
            entity.SetCollisionMaskFriendly(0);
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            if (projectile.GetRelativeY() <= 0)
            {
                var range = projectile.GetRange();
                var damage = projectile.GetDamage();
                TNT.Explode(projectile, range, damage);
                projectile.Remove();
            }
        }
    }
}
